using GraphApi.Models.NTF.Notificaciones;namespace GraphApi.Services.NTF.Notificaciones{    /// <summary>    /// Define las operaciones de negocio y persistencia para Notificaciones.    /// </summary>    public interface INotificacionesService    {        /// <summary>        /// Obtiene la lista de Notificaciones con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadNotificaciones>> GetNotificaciones(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Notificaciones con filtros opcionales.        /// </summary>        /// <param name="notificacionID">Filtro opcional para NotificacionID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="titulo">Filtro opcional para Titulo.</param>        /// <param name="mensaje">Filtro opcional para Mensaje.</param>        /// <param name="leido">Filtro opcional para Leido.</param>        /// <param name="fechaCreacionNotificacion">Filtro opcional para FechaCreacionNotificacion.</param>        /// <param name="tipoNotificacionID">Filtro opcional para TipoNotificacionID.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetNotificacionesDynamic(            int? notificacionID,            int? usuarioID,            string? titulo,            string? mensaje,            bool? leido,            DateTime? fechaCreacionNotificacion,            int? tipoNotificacionID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Notificacione.        /// </summary>        /// <param name="objInput">Datos para crear el Notificacione.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadNotificaciones> CreateNotificaciones(            clCreateNotificaciones objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Notificacione.        /// </summary>        /// <param name="objInput">Datos para actualizar el Notificacione, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadNotificaciones?> UpdateNotificaciones(            clUpdateNotificaciones objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Notificacione por su ID.        /// </summary>        /// <param name="nNotificacionesID">ID del Notificacione a eliminar.</param>        Task<bool> DeleteNotificaciones(int nNotificacionesID);    }}